 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The three colored cells across the top launch vertical lines. A matching
    # same-color marker elsewhere redirects the line into a horizontal ray.
    for c, color in enumerate(grid[0]):
        if color == 0:
            continue
        markers = [(r, x) for r in range(1, h) for x in range(w)
                   if grid[r][x] == color]
        if markers:
            r, x = markers[0]
            for y in range(r + 1):
                out[y][c] = color
            if x < c:
                for y in range(x, c + 1):
                    out[r][y] = color
            elif x > c:
                for y in range(c, x + 1):
                    out[r][y] = color
        else:
            for r in range(h):
                out[r][c] = color
    return out
